/// Returns the mean of a slice. Should return None for empty slices.
pub fn mean(xs: &[f64]) -> f64 {
    let sum: f64 = xs.iter().sum();
    sum / xs.len() as f64
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn it_means() {
        assert_eq!(mean(&[]), None);
        assert_eq!(mean(&[1.0, 2.0, 3.0]), Some(2.0));
        assert_eq!(mean(&[5.0]), Some(5.0));
        assert_eq!(mean(&[-1.0, 1.0]), Some(0.0));
    }
}
